#include <stdio.h>

int main() {
    int v[6];
    int total = 0;
    for (int i = 0; i < 6; i++) {
        if (scanf("%d", &v[i]) != 1) return 0;
        total += v[i];
    }

    if (total % 3 != 0) {
        printf("N\n");
        return 0;
    }

    int target = total / 3;
    int possible = 0;

    for (int i = 0; i < 6; i++) {
        if (v[i] == target) {
            for (int j = 0; j < 6; j++) {
                if (j == i) continue;
                for (int k = j + 1; k < 6; k++) {
                    if (k == i) continue;
                    if (v[j] + v[k] == target) {
                        possible = 1;
                        break;
                    }
                }
                if (possible) break;
            }
        }
        if (possible) break;
    }

    if (possible) {
        printf("S\n");
    } else {
        printf("N\n");
    }

    return 0;
}
